"use strict";(globalThis.webpackChunkdocs_workspace=globalThis.webpackChunkdocs_workspace||[]).push([[4253],{73911(n,e,t){t.r(e),t.d(e,{assets:()=>c,contentTitle:()=>o,default:()=>d,frontMatter:()=>i,metadata:()=>s,toc:()=>u});const s=JSON.parse('{"id":"basic/06","title":"\u8de8\u5e73\u53f0\u7f16\u8bd1","description":"","source":"@site/content/tauri/docs/basic/06.md","sourceDirName":"basic","slug":"/basic/06","permalink":"/tauri-doc/docs/basic/06","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"\u96c6\u6210 WebAssembly","permalink":"/tauri-doc/docs/basic/05"},"next":{"title":"07","permalink":"/tauri-doc/docs/basic/07"}}');var a=t(74848),r=t(28453);const i={},o="\u8de8\u5e73\u53f0\u7f16\u8bd1",c={},u=[];function l(n){const e={code:"code",h1:"h1",header:"header",pre:"pre",...(0,r.R)(),...n.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(e.header,{children:(0,a.jsx)(e.h1,{id:"\u8de8\u5e73\u53f0\u7f16\u8bd1",children:"\u8de8\u5e73\u53f0\u7f16\u8bd1"})}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{children:"lencx\nlencx\n{\u6298\u817e \u21cc \u8ff7\u832b \u21cc \u601d\u8003]ing\uff0c\u5728\u8def\u4e0a...\n\u200b\u5173\u6ce8\u4ed6\n15 \u4eba\u8d5e\u540c\u4e86\u8be5\u6587\u7ae0\n\u4ed3\u5e93\uff1alencx/OhMyBox\n\u9605\u8bfb\u539f\u6587\uff08\u9996\u53d1\u4e8e GitHub\uff09\n\u5173\u6ce8\u300a\u6d6e\u4e4b\u9759\u300b\u516c\u4f17\u53f7\uff0c\u79c1\u4fe1\u4f5c\u8005\uff0c\u8fdb Tauri \u6280\u672f\u4ea4\u6d41\u7fa4\n\u80cc\u666f\nTauri \u4e25\u91cd\u4f9d\u8d56\u539f\u751f\u5e93\u548c\u5de5\u5177\u94fe\uff0c\u56e0\u6b64\u76ee\u524d\u65e0\u6cd5\u5728\u67d0\u4e00\u5e73\u53f0\u5b9e\u73b0\u4ea4\u53c9\u7f16\u8bd1\u3002\u6700\u4f73\u9009\u62e9\u662f\u4f7f\u7528\u6258\u7ba1\u5728 GitHub Action\u3001Azure Pipelines\u3001GitLab \u6216\u5176\u4ed6\u9009\u9879\u4e0a\u7684 CI/CD \u7ba1\u9053\u8fdb\u884c\u7f16\u8bd1\u3002\u7ba1\u9053\u53ef\u4ee5\u540c\u65f6\u4e3a\u6bcf\u4e2a\u5e73\u53f0\u8fd0\u884c\u7f16\u8bd1\uff0c\u4f7f\u7f16\u8bd1\u548c\u53d1\u5e03\u8fc7\u7a0b\u66f4\u52a0\u5bb9\u6613\u3002\n\n\u4e3a\u4e86\u4fbf\u4e8e\u8bbe\u7f6e\uff0c\u5b98\u65b9\u76ee\u524d\u63d0\u4f9b Tauri Action\u3002\u8fd9\u662f\u4e00\u4e2a GitHub Action\uff0c\u53ef\u5728\u6240\u6709\u652f\u6301\u7684\u5e73\u53f0\u4e0a\u8fd0\u884c\uff0c\u7f16\u8bd1\u8f6f\u4ef6\uff0c\u751f\u6210\u5e94\u7528\u7a0b\u5e8f\u5b89\u88c5\u5305\uff0c\u5e76\u5c06\u53d1\u5e03\u5230 GitHub Releases\u3002\n\nGitHub Action\n\u4ece\u6784\u601d\u5230\u751f\u4ea7\uff0c\u81ea\u52a8\u5316\u5de5\u4f5c\u6d41\u7a0b\n\u5229\u7528 GitHub Actions\uff0c\u5728\u4f60\u7684\u4ed3\u5e93\u4e2d\u81ea\u52a8\u5316\u3001\u5b9a\u5236\u548c\u6267\u884c\u4f60\u7684\u8f6f\u4ef6\u5f00\u53d1\u5de5\u4f5c\u6d41\u7a0b\u3002\u4f60\u53ef\u4ee5\u53d1\u73b0\u3001\u521b\u5efa\u548c\u5171\u4eab\u64cd\u4f5c\uff0c\u4ee5\u6267\u884c\u4f60\u60f3\u8981\u7684\u4efb\u4f55\u5de5\u4f5c\uff0c\u5305\u62ec CI/CD\uff0c\u5e76\u5728\u4e00\u4e2a\u5b8c\u5168\u5b9a\u5236\u7684\u5de5\u4f5c\u6d41\u7a0b\u4e2d\u7ec4\u5408\u64cd\u4f5c\u3002\n\n\u4f7f\u7528 Action\n\u521b\u5efa release.yml\n\u5728\u9879\u76ee\u6839\u8def\u5f84\u4e0b\u521b\u5efa .github/workflows \u76ee\u5f55\uff0c\u5728 .github/workflows \u4e0b\u521b\u5efa release.yml\uff08\u6587\u4ef6\u540d\u81ea\u5b9a\u4e49\uff09 \u6587\u4ef6\u3002\u5c06\u4ee5\u4e0b\u5185\u5bb9\u590d\u5236\u5230\u6587\u4ef6\u4e2d\uff1a\n\n# \u53ef\u9009\uff0c\u5c06\u663e\u793a\u5728 GitHub \u5b58\u50a8\u5e93\u7684\u201c\u64cd\u4f5c\u201d\u9009\u9879\u5361\u4e2d\u7684\u5de5\u4f5c\u6d41\u540d\u79f0\nname: Release CI\n\n# \u6307\u5b9a\u6b64\u5de5\u4f5c\u6d41\u7684\u89e6\u53d1\u5668\non:\n  push:\n    # \u5339\u914d\u7279\u5b9a\u6807\u7b7e (refs/tags)\n    tags:\n      - 'v*' # \u63a8\u9001\u4e8b\u4ef6\u5339\u914d v*, \u4f8b\u5982 v1.0\uff0cv20.15.10 \u7b49\u6765\u89e6\u53d1\u5de5\u4f5c\u6d41\n\n# \u9700\u8981\u8fd0\u884c\u7684\u4f5c\u4e1a\u7ec4\u5408\njobs:\n  # \u4efb\u52a1\uff1a\u521b\u5efa release \u7248\u672c\n  create-release:\n    runs-on: ubuntu-latest\n    outputs:\n      RELEASE_UPLOAD_ID: ${{ steps.create_release.outputs.id }}\n\n    steps:\n      - uses: actions/checkout@v2\n      # \u67e5\u8be2\u7248\u672c\u53f7\uff08tag\uff09\n      - name: Query version number\n        id: get_version\n        shell: bash\n        run: |\n          echo \"using version tag ${GITHUB_REF:10}\"\n          echo ::set-output name=version::\"${GITHUB_REF:10}\"\n\n      # \u6839\u636e\u67e5\u8be2\u5230\u7684\u7248\u672c\u53f7\u521b\u5efa release\n      - name: Create Release\n        id: create_release\n        uses: actions/create-release@v1\n        env:\n          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n        with:\n          tag_name: '${{ steps.get_version.outputs.VERSION }}'\n          release_name: 'app ${{ steps.get_version.outputs.VERSION }}'\n          body: 'See the assets to download this version and install.'\n\n  # \u7f16\u8bd1 Tauri\n  build-tauri:\n    needs: create-release\n    strategy:\n      fail-fast: false\n      matrix:\n        platform: [macos-latest, ubuntu-latest, windows-latest]\n\n    runs-on: ${{ matrix.platform }}\n    steps:\n      - uses: actions/checkout@v2\n\n     # \u5b89\u88c5 Node.js\n      - name: Setup node\n        uses: actions/setup-node@v1\n        with:\n          node-version: 16\n\n      # \u5b89\u88c5 Rust\n      - name: Install Rust stable\n        uses: actions-rs/toolchain@v1\n        with:\n          toolchain: stable\n\n      # \u4f7f\u7528 Rust \u7f13\u5b58\uff0c\u52a0\u5feb\u5b89\u88c5\u901f\u5ea6\n      - uses: Swatinem/rust-cache@v1\n\n      - name: install dependencies (ubuntu only)\n        if: matrix.platform == 'ubuntu-latest'\n        run: |\n          sudo apt-get update\n          sudo apt-get install -y libgtk-3-dev webkit2gtk-4.0 libappindicator3-dev librsvg2-dev patchelf\n\n      # \u53ef\u9009\uff0c\u5982\u679c\u9700\u8981\u5c06 Rust \u7f16\u8bd1\u4e3a wasm\uff0c\u5219\u5b89\u88c5 wasm-pack\n      - uses: jetli/wasm-pack-action@v0.3.0\n        with:\n          # Optional version of wasm-pack to install(eg. 'v0.9.1', 'latest')\n          version: v0.9.1\n\n      # \u53ef\u9009\uff0c\u5982\u679c\u9700\u8981\u4f7f\u7528 rsw \u6784\u5efa wasm\uff0c\u5219\u5b89\u88c5 rsw\n      - name: Install rsw\n        run: cargo install rsw\n\n      # \u83b7\u53d6 yarn \u7f13\u5b58\u8def\u5f84\n      - name: Get yarn cache directory path\n        id: yarn-cache-dir-path\n        run: echo \"::set-output name=dir::$(yarn config get cacheFolder)\"\n\n      # \u4f7f\u7528 yarn \u7f13\u5b58\n      - name: Yarn cache\n        uses: actions/cache@v2\n        id: yarn-cache # use this to check for `cache-hit` (`steps.yarn-cache.outputs.cache-hit != 'true'`)\n        with:\n          path: ${{ steps.yarn-cache-dir-path.outputs.dir }}\n          key: ${{ runner.os }}-yarn-${{ hashFiles('/yarn.lock') }}\n          restore-keys: |\n            ${{ runner.os }}-yarn-\n\n      # \u5b89\u88c5\u4f9d\u8d56\u6267\u884c\u6784\u5efa\uff0c\u4ee5\u53ca\u63a8\u9001 github release\n      - name: Install app dependencies and build it\n        run: yarn && yarn build\n      - uses: tauri-apps/tauri-action@v0\n        env:\n          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n        with:\n          releaseId: ${{ needs.create-release.outputs.RELEASE_UPLOAD_ID }}\n\u5177\u4f53\u53ef\u4ee5\u53c2\u8003 OhMyBox/.github/workflows/release.yml\n\n\u89e6\u53d1 Action\n\u4f7f\u7528 GitHub Tag \u6765\u89e6\u53d1 Action\n# \u521b\u5efa tag\ngit tag v0.1.0\n\n# \u63a8\u9001 tag\ngit push --tag\n\n\n\u5e38\u89c1\u95ee\u9898\nError: Resource not accessible by integration\nrelease.yml \u4e2d\u7684 GitHub \u73af\u5883\u4ee4\u724c\u200b GITHUB_TOKEN \u7531 GitHub \u4e3a\u6bcf\u4e2a\u8fd0\u884c\u7684\u5de5\u4f5c\u6d41\u81ea\u52a8\u9881\u53d1\uff0c\u65e0\u9700\u8fdb\u4e00\u6b65\u914d\u7f6e\uff0c\u8fd9\u610f\u5473\u7740\u6ca1\u6709\u79d8\u5bc6\u6cc4\u9732\u7684\u98ce\u9669\u3002\u4f46\u662f\uff0c\u6b64\u4ee4\u724c\u5728\u9ed8\u8ba4\u60c5\u51b5\u4e0b\u4ec5\u5177\u6709\u8bfb\u53d6\u6743\u9650\uff0c\u5728\u8fd0\u884c\u5de5\u4f5c\u6d41\u65f6\u53ef\u80fd\u4f1a\u6536\u5230 Resource not accessible by integration\uff08\u8d44\u6e90\u65e0\u6cd5\u901a\u8fc7\u96c6\u6210\u8bbf\u95ee\uff09\u9519\u8bef\u3002\u5982\u679c\u53d1\u751f\u8fd9\u79cd\u60c5\u51b5\uff0c\u9700\u8981\u4e3a\u6b64\u4ee4\u724c\u6dfb\u52a0\u5199\u5165\u6743\u9650\u3002\u4e3a\u6b64\uff0c\u8bf7\u524d\u5f80 GitHub \u4ed3\u5e93 Settings\uff0c\u7136\u540e\u9009\u62e9 Actions\uff0c\u5411\u4e0b\u6eda\u52a8\u5230 Workflow permissions\uff08\u5de5\u4f5c\u6d41\u6743\u9650\uff09\u5e76\u9009\u4e2d Read and write permissions\uff08\u8bfb\u53d6\u548c\u5199\u5165\u6743\u9650\uff09\u3002\n\nSettings -> Actions -> General -> Workflow permissions -> Read and write permissions\nAction \u610f\u5916\u7ec8\u6b62\n\u5982\u679c Action \u56e0\u67d0\u4e9b\u539f\u56e0\uff08\u5982\u7f13\u5b58\u9519\u8bef\uff0c\u4f9d\u8d56\u4e0b\u8f7d\u5931\u8d25\u7b49\uff09\u7ec8\u6b62\u5de5\u4f5c\u6d41\uff0c\u4e0d\u9700\u8981\u91cd\u65b0\u521b\u5efa tag \u6765\u89e6\u53d1\u5de5\u4f5c\u6d41\uff0c\u53ef\u4ee5\u901a\u8fc7 Re-run all jobs \u6309\u94ae\u6765\u91cd\u65b0\u89e6\u53d1\u3002\n"})})]})}function d(n={}){const{wrapper:e}={...(0,r.R)(),...n.components};return e?(0,a.jsx)(e,{...n,children:(0,a.jsx)(l,{...n})}):l(n)}},28453(n,e,t){t.d(e,{R:()=>i,x:()=>o});var s=t(96540);const a={},r=s.createContext(a);function i(n){const e=s.useContext(r);return s.useMemo(function(){return"function"==typeof n?n(e):{...e,...n}},[e,n])}function o(n){let e;return e=n.disableParentContext?"function"==typeof n.components?n.components(a):n.components||a:i(n.components),s.createElement(r.Provider,{value:e},n.children)}}}]);